//! `toUpperCase` parity (R-RUSTPORT-P4-29-TEXT-FONTS-Q1, P4-25 §3.3: "do
//! testu w RR-T8b").
//!
//! `tests/fixtures/text/upper.tsv` lists every code point whose
//! `String.prototype.toUpperCase` result (V8 in node v22, generated by
//! `gen.mjs`) differs from the input; `city_names.txt` holds every string of
//! `gra/data/city-names-pools.json` at pin `edb8fb56`.

use std::collections::HashMap;

use civ_renderer::raster::text::js_to_upper_case;

fn fixture(rel: &str) -> String {
    let p = format!("{}/tests/fixtures/text/{rel}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{p}: {e}"))
}

fn js_table() -> HashMap<char, String> {
    fixture("upper.tsv")
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| {
            let (cp, up) = l.split_once('\t').expect("row");
            let c = char::from_u32(u32::from_str_radix(cp, 16).expect("hex")).expect("char");
            let s: String = up
                .split(' ')
                .map(|h| char::from_u32(u32::from_str_radix(h, 16).expect("hex")).expect("char"))
                .collect();
            (c, s)
        })
        .collect()
}

fn js_upper(t: &HashMap<char, String>, s: &str) -> String {
    s.chars()
        .map(|c| t.get(&c).cloned().unwrap_or_else(|| c.to_string()))
        .collect()
}

#[test]
fn the_22_city_name_letters_upper_case_like_js() {
    let t = js_table();
    // Lower-case forms of the 22 letters of P4-25 §3.3 → expected upper.
    let lower = "öłüńóøşğçążáñéśęúříåäź";
    let upper = "ÖŁÜŃÓØŞĞÇĄŻÁÑÉŚĘÚŘÍÅÄŹ";
    assert_eq!(js_upper(&t, lower), upper);
    assert_eq!(js_to_upper_case(lower), upper);
    // Special casing: ß → SS, ı → I (P4-25 §3.3).
    assert_eq!(js_to_upper_case("ßı"), js_upper(&t, "ßı"));
    assert_eq!(js_to_upper_case("ßı"), "SSI");
}

#[test]
fn all_city_names_upper_case_like_js() {
    let t = js_table();
    let names = fixture("city_names.txt");
    let mut n = 0;
    for name in names.lines() {
        let web = js_upper(&t, name.trim());
        assert_eq!(js_to_upper_case(name.trim()), web, "{name:?}");
        n += 1;
    }
    assert_eq!(n, 1665, "P4-25 §3.3 counts 1 665 strings");
}

#[test]
fn whole_unicode_table_agrees_on_european_scripts() {
    // V8's ICU and Rust's std may be on different Unicode versions; for the
    // Latin, Greek, Cyrillic and Armenian blocks (U+0000–U+058F, plus Latin
    // Extended Additional U+1E00–U+1EFF) the mappings must be identical.
    let t = js_table();
    let mut diffs = Vec::new();
    let mut total = 0;
    for cp in (0u32..=0x58F).chain(0x1E00..=0x1EFF) {
        let Some(c) = char::from_u32(cp) else {
            continue;
        };
        let web = t.get(&c).cloned().unwrap_or_else(|| c.to_string());
        if js_to_upper_case(&c.to_string()) != web {
            diffs.push(format!("U+{cp:04X}"));
        }
        total += 1;
    }
    assert!(diffs.is_empty(), "differences: {diffs:?}");
    // Report differences elsewhere (informational: Unicode version skew).
    let mut other = 0;
    for (c, web) in &t {
        if js_to_upper_case(&c.to_string()) != *web {
            other += 1;
        }
    }
    println!("checked {total} code points strictly; {other} differences in the whole table");
}
